const ArgumentType = require('../../extension-support/argument-type');
const BlockType = require('../../extension-support/block-type');
const Cast = require('../../util/cast');
const MathUtil = require('../../util/math-util');

/* eslint-disable indent, max-len */

/**
 * Icon svg to be displayed in the blocks category menu, encoded as a data URI.
 * @type {string}
 */
const menuIconURI = 'data:image/png;base64,';

const rotateRightIconURI = 'data:image/svg+xml;base64,';
const rotateLeftIconURI = 'data:image/svg+xml;base64,';

class NitroBoltCameraBlocks {
  constructor (runtime) {
    this.runtime = runtime;
    runtime.setRuntimeOptions({fencing: false});
    runtime.on('RUNTIME_DISPOSED', () => runtime.renderer.resetCameras());
  }

  /**
   * @returns {object} metadata for this extension and its blocks.
   */
  getInfo () {
    return {
      id: 'camera',
      name: 'Camera',
      menuIconURI: menuIconURI,
      color1: '#2a835f',
      blocks: [
        {
          opcode: 'createCamera',
          blockType: BlockType.COMMAND,
          text: 'create camera named [CAMERA]',
          arguments: {
            CAMERA: {
              type: ArgumentType.STRING,
              defaultValue: 'my camera'
            }
          }
        },
        {
          opcode: 'deleteCamera',
          blockType: BlockType.COMMAND,
          text: 'delete camera named [CAMERA]',
          arguments: {
            CAMERA: {
              type: ArgumentType.STRING,
              menu: 'cameras',
              defaultValue: 'my camera'
            }
          }
        },

        '---',

        {
          opcode: 'bindCamera',
          blockType: BlockType.COMMAND,
          text: 'bind [TARGETS] to [CAMERAS] camera',
          arguments: {
            TARGETS: {
              type: ArgumentType.STRING,
              menu: 'targets'
            },
            CAMERAS: {
              type: ArgumentType.STRING,
              menu: 'cameras',
              defaultValue: 'default'
            }
          }
        },
        {
          opcode: 'currentCamera',
          blockType: BlockType.REPORTER,
          text: 'camera of [TARGETS]',
          arguments: {
            TARGETS: {
              type: ArgumentType.STRING,
              menu: 'targets'
            }
          }
        },
        {
          opcode: 'allCameras',
          blockType: BlockType.ARRAY,
          text: 'all cameras'
        },

        '---',

        {
          opcode: 'moveCamera',
          blockType: BlockType.COMMAND,
          text: 'move [CAMERAS] camera to x: [X] y: [Y]',
          switches: ['changeCameraBy'],
          arguments: {
            CAMERAS: {
              type: ArgumentType.STRING,
              menu: 'cameras',
              defaultValue: 'default'
            },
            X: {
              type: ArgumentType.NUMBER
            },
            Y: {
              type: ArgumentType.NUMBER
            }
          }
        },
        {
          opcode: 'moveCameraToTarget',
          blockType: BlockType.COMMAND,
          text: 'move [CAMERAS] camera to [TARGETS]',
          arguments: {
            CAMERAS: {
              type: ArgumentType.STRING,
              menu: 'cameras',
              defaultValue: 'default'
            },
            TARGETS: {
              type: ArgumentType.STRING,
              menu: 'targets'
            }
          }
        },
        {
          opcode: 'changeCameraBy',
          blockType: BlockType.COMMAND,
          text: 'change [CAMERAS] camera by x: [X] y: [Y]',
          switches: ['moveCamera'],
          arguments: {
            CAMERAS: {
              type: ArgumentType.STRING,
              menu: 'cameras',
              defaultValue: 'default'
            },
            X: {
              type: ArgumentType.NUMBER
            },
            Y: {
              type: ArgumentType.NUMBER
            }
          }
        },

        '---',

        {
          opcode: 'moveCameraSteps',
          blockType: BlockType.COMMAND,
          text: 'move [CAMERAS] camera [STEPS] steps',
          arguments: {
            CAMERAS: {
              type: ArgumentType.STRING,
              menu: 'cameras',
              defaultValue: 'default'
            },
            STEPS: {
              type: ArgumentType.NUMBER,
              defaultValue: 10
            }
          }
        },
        {
          opcode: 'setCameraX',
          blockType: BlockType.COMMAND,
          text: 'set [CAMERAS] camera x to [X]',
          switches: ['changeCameraX'],
          arguments: {
            CAMERAS: {
              type: ArgumentType.STRING,
              menu: 'cameras',
              defaultValue: 'default'
            },
            X: {
              type: ArgumentType.NUMBER
            }
          }
        },
        {
          opcode: 'changeCameraX',
          blockType: BlockType.COMMAND,
          text: 'change [CAMERAS] camera x by [X]',
          switches: ['setCameraX'],
          arguments: {
            CAMERAS: {
              type: ArgumentType.STRING,
              menu: 'cameras',
              defaultValue: 'default'
            },
            X: {
              type: ArgumentType.NUMBER,
              defaultValue: 10
            }
          }
        },
        {
          opcode: 'setCameraY',
          blockType: BlockType.COMMAND,
          text: 'set [CAMERAS] camera y to [Y]',
          switches: ['changeCameraY'],
          arguments: {
            CAMERAS: {
              type: ArgumentType.STRING,
              menu: 'cameras',
              defaultValue: 'default'
            },
            Y: {
              type: ArgumentType.NUMBER
            }
          }
        },
        {
          opcode: 'changeCameraY',
          blockType: BlockType.COMMAND,
          text: 'change [CAMERAS] camera y by [Y]',
          switches: ['setCameraY'],
          arguments: {
            CAMERAS: {
              type: ArgumentType.STRING,
              menu: 'cameras',
              defaultValue: 'default'
            },
            Y: {
              type: ArgumentType.NUMBER,
              defaultValue: 10
            }
          }
        },
        {
          opcode: 'cameraXPosition',
          blockType: BlockType.REPORTER,
          text: '[CAMERAS] camera x position',
          disableMonitor: true,
          switches: ['cameraYPosition', 'cameraDirection', 'cameraZoom'],
          arguments: {
            CAMERAS: {
              type: ArgumentType.STRING,
              menu: 'cameras',
              defaultValue: 'default'
            }
          }
        },
        {
          opcode: 'cameraYPosition',
          blockType: BlockType.REPORTER,
          text: '[CAMERAS] camera y position',
          disableMonitor: true,
          switches: ['cameraXPosition', 'cameraDirection', 'cameraZoom'],
          arguments: {
            CAMERAS: {
              type: ArgumentType.STRING,
              menu: 'cameras',
              defaultValue: 'default'
            }
          }
        },

        '---',

        {
          opcode: 'turnCameraRight',
          blockType: BlockType.COMMAND,
          text: 'turn [CAMERAS] camera [ICON] [DEGREES] degrees',
          switches: ['turnCameraLeft'],
          arguments: {
            CAMERAS: {
              type: ArgumentType.STRING,
              menu: 'cameras',
              defaultValue: 'default'
            },
            ICON: {
              type: ArgumentType.IMAGE,
              dataURI: rotateRightIconURI
            },
            DEGREES: {
              type: ArgumentType.ANGLE,
              defaultValue: 15
            }
          }
        },
        {
          opcode: 'turnCameraLeft',
          blockType: BlockType.COMMAND,
          text: 'turn [CAMERAS] camera [ICON] [DEGREES] degrees',
          switches: ['turnCameraRight'],
          arguments: {
            CAMERAS: {
              type: ArgumentType.STRING,
              menu: 'cameras',
              defaultValue: 'default'
            },
            ICON: {
              type: ArgumentType.IMAGE,
              dataURI: rotateLeftIconURI
            },
            DEGREES: {
              type: ArgumentType.ANGLE,
              defaultValue: 15
            }
          }
        },

        '---',

        {
          opcode: 'setCameraDirection',
          blockType: BlockType.COMMAND,
          text: 'set [CAMERAS] camera direction to [DIRECTION]',
          arguments: {
            CAMERAS: {
              type: ArgumentType.STRING,
              menu: 'cameras',
              defaultValue: 'default'
            },
            DIRECTION: {
              type: ArgumentType.ANGLE,
              defaultValue: 90
            }
          }
        },
        {
          opcode: 'pointCameraTowardsTarget',
          blockType: BlockType.COMMAND,
          text: 'point [CAMERAS] camera towards [TARGETS]',
          arguments: {
            CAMERAS: {
              type: ArgumentType.STRING,
              menu: 'cameras',
              defaultValue: 'default'
            },
            TARGETS: {
              type: ArgumentType.STRING,
              menu: 'targets'
            }
          }
        },
        {
          opcode: 'cameraDirection',
          blockType: BlockType.REPORTER,
          text: '[CAMERAS] camera direction',
          disableMonitor: true,
          switches: ['cameraXPosition', 'cameraYPosition', 'cameraZoom'],
          arguments: {
            CAMERAS: {
              type: ArgumentType.STRING,
              menu: 'cameras',
              defaultValue: 'default'
            }
          }
        },

        '---',

        {
          opcode: 'setCameraZoom',
          blockType: BlockType.COMMAND,
          text: 'set [CAMERAS] camera zoom to [SIZE] %',
          switches: ['changeCameraZoom'],
          arguments: {
            CAMERAS: {
              type: ArgumentType.STRING,
              menu: 'cameras',
              defaultValue: 'default'
            },
            SIZE: {
              type: ArgumentType.NUMBER,
              defaultValue: 100
            }
          }
        },
        {
          opcode: 'changeCameraZoom',
          blockType: BlockType.COMMAND,
          text: 'change [CAMERAS] camera zoom by [SIZE]',
          switches: ['setCameraZoom'],
          arguments: {
            CAMERAS: {
              type: ArgumentType.STRING,
              menu: 'cameras',
              defaultValue: 'default'
            },
            SIZE: {
              type: ArgumentType.NUMBER,
              defaultValue: 10
            }
          }
        },
        {
          opcode: 'cameraZoom',
          blockType: BlockType.REPORTER,
          text: '[CAMERAS] camera zoom',
          disableMonitor: true,
          switches: ['cameraXPosition', 'cameraYPosition', 'cameraDirection'],
          arguments: {
            CAMERAS: {
              type: ArgumentType.STRING,
              menu: 'cameras',
              defaultValue: 'default'
            }
          }
        }
      ],
      menus: {
        targets: {
          acceptReporters: true,
          items: 'getTargets'
        },
        cameras: {
          acceptReporters: true,
          acceptText: true,
          items: 'getCameras'
        }
      }
    };
  }

  createCamera (args) {
    this.runtime.renderer.createCamera(Cast.toString(args.CAMERA).trim());
  }

  deleteCamera (args) {
    const name = Cast.toString(args.CAMERA);
    if (this.runtime.renderer.deleteCamera(name)) {
      for (let i = 0; i < this.runtime.targets.length; i++) {
        if (this.runtime.targets[i].cameraName === name) {
          this.runtime.targets[i].cameraName = 'default';
          this.runtime.targets[i].emitVisualChange();
          if (this.runtime.targets[i].isOriginal) this.runtime.requestTargetsUpdate(this.runtime.targets[i]);
        }
      }
    }
  }

  bindCamera (args, util) {
    const target = this._getTarget(args.TARGETS, util);
    const name = Cast.toString(args.CAMERAS);
    if (!target || !this._getCamera(name)) return;
    const targets = target.isStage ? [target] : target.sprite.clones;
    for (let i = 0; i < targets.length; i++) {
      targets[i].cameraName = name;
      this.runtime.renderer.bindDrawableToCamera(targets[i].drawableID, name);
      targets[i].emitVisualChange();
    }
    this.runtime.requestTargetsUpdate(target.isOriginal ? target : target.sprite.clones[0]);
    this.runtime.requestRedraw();
  }

  currentCamera (args, util) {
    const target = this._getTarget(args.TARGETS, util);
    return target ? target.cameraName : '';
  }

  allCameras () {
    return this.getCameras();
  }

  moveCamera (args) {
    this._update(args.CAMERAS, {x: Cast.toNumber(args.X), y: Cast.toNumber(args.Y)});
  }

  moveCameraToTarget (args, util) {
    const target = this._getTarget(args.TARGETS, util);
    if (target) this._update(args.CAMERAS, {x: target.x, y: target.y});
  }

  changeCameraBy (args) {
    const camera = this._getCamera(args.CAMERAS);
    if (camera) this._update(args.CAMERAS, {x: camera.x + Cast.toNumber(args.X), y: camera.y + Cast.toNumber(args.Y)});
  }

  moveCameraSteps (args) {
    const camera = this._getCamera(args.CAMERAS);
    if (!camera) return;
    const radians = MathUtil.degToRad(90 - camera.direction);
    const steps = Cast.toNumber(args.STEPS);
    this._update(args.CAMERAS, {x: camera.x + (steps * Math.cos(radians)), y: camera.y + (steps * Math.sin(radians))});
  }

  setCameraX (args) {
    this._update(args.CAMERAS, {x: Cast.toNumber(args.X)});
  }

  changeCameraX (args) {
    const camera = this._getCamera(args.CAMERAS);
    if (camera) this._update(args.CAMERAS, {x: camera.x + Cast.toNumber(args.X)});
  }

  setCameraY (args) {
    this._update(args.CAMERAS, {y: Cast.toNumber(args.Y)});
  }

  changeCameraY (args) {
    const camera = this._getCamera(args.CAMERAS);
    if (camera) this._update(args.CAMERAS, {y: camera.y + Cast.toNumber(args.Y)});
  }

  cameraXPosition (args) {
    const camera = this._getCamera(args.CAMERAS);
    return camera ? camera.x : 0;
  }

  cameraYPosition (args) {
    const camera = this._getCamera(args.CAMERAS);
    return camera ? camera.y : 0;
  }

  turnCameraRight (args) {
    const camera = this._getCamera(args.CAMERAS);
    if (camera) this._update(args.CAMERAS, {direction: MathUtil.wrapClamp(camera.direction + Cast.toNumber(args.DEGREES), -179, 180)});
  }

  turnCameraLeft (args) {
    const camera = this._getCamera(args.CAMERAS);
    if (camera) this._update(args.CAMERAS, {direction: MathUtil.wrapClamp(camera.direction - Cast.toNumber(args.DEGREES), -179, 180)});
  }

  setCameraDirection (args) {
    this._update(args.CAMERAS, {direction: MathUtil.wrapClamp(Cast.toNumber(args.DIRECTION), -179, 180)});
  }

  pointCameraTowardsTarget (args, util) {
    const camera = this._getCamera(args.CAMERAS);
    const target = this._getTarget(args.TARGETS, util);
    if (!camera || !target) return;
    const direction = 90 - MathUtil.radToDeg(Math.atan2(target.y - camera.y, target.x - camera.x));
    this._update(args.CAMERAS, {direction: MathUtil.wrapClamp(direction, -179, 180)});
  }

  cameraDirection (args) {
    const camera = this._getCamera(args.CAMERAS);
    return camera ? camera.direction : 90;
  }

  setCameraZoom (args) {
    this._update(args.CAMERAS, {zoom: Cast.toNumber(args.SIZE)});
  }

  changeCameraZoom (args) {
    const camera = this._getCamera(args.CAMERAS);
    if (camera) this._update(args.CAMERAS, {zoom: camera.zoom + Cast.toNumber(args.SIZE)});
  }

  cameraZoom (args) {
    const camera = this._getCamera(args.CAMERAS);
    return camera ? camera.zoom : 100;
  }

  getTargets () {
    const items = [
      {
        text: 'myself',
        value: '_myself_'
      },
      {
        text: 'Stage',
        value: '_stage_'
      }
    ];
    for (let i = 0; i < this.runtime.targets.length; i++) {
      const target = this.runtime.targets[i];
      if (!target.isStage && target.isOriginal) items.push(target.getName());
    }
    return items;
  }

  getCameras () {
    return this.runtime.renderer.getCameraNames();
  }

  _getTarget (value, util) {
    const name = Cast.toString(value);
    if (name === '_myself_') return util.target;
    if (name === '_stage_') return this.runtime.getTargetForStage();
    return this.runtime.getSpriteTargetByName(name);
  }

  _getCamera (value) {
    return this.runtime.renderer.getCamera(Cast.toString(value));
  }

  _update (value, properties) {
    const name = Cast.toString(value);
    if (!this.runtime.renderer.updateCamera(name, properties)) return;
    this._requestCameraTargetUpdates(name);
    this.runtime.requestRedraw();
  }

  _requestCameraTargetUpdates (name) {
    for (let i = 0; i < this.runtime.targets.length; i++) {
      const target = this.runtime.targets[i];
      if (target.cameraName !== name) continue;
      target.emitVisualChange();
      if (target.isOriginal) this.runtime.requestTargetsUpdate(target);
    }
  }

}

module.exports = NitroBoltCameraBlocks;
